create extension if not exists pgcrypto;
create table if not exists public.library_items (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,storage_path text not null unique,file_name text not null,mime_type text,size_bytes bigint not null default 0 check (size_bytes >= 0),source_conversation_id uuid null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists library_items_user_created_idx on public.library_items(user_id,created_at desc); alter table public.library_items enable row level security;
drop policy if exists "library own select" on public.library_items; drop policy if exists "library own insert" on public.library_items; drop policy if exists "library own delete" on public.library_items;
create policy "library own select" on public.library_items for select using(auth.uid()=user_id); create policy "library own insert" on public.library_items for insert with check(auth.uid()=user_id); create policy "library own delete" on public.library_items for delete using(auth.uid()=user_id);
create table if not exists public.memories (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,content text not null check(char_length(content)<=12000),source text not null default 'user',metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists memories_user_updated_idx on public.memories(user_id,updated_at desc); alter table public.memories enable row level security; drop policy if exists "memories own all" on public.memories; create policy "memories own all" on public.memories for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
insert into storage.buckets(id,name,public,file_size_limit) values('user-library','user-library',false,52428800) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit;
drop policy if exists "library storage own select" on storage.objects; drop policy if exists "library storage own insert" on storage.objects; drop policy if exists "library storage own delete" on storage.objects;
create policy "library storage own select" on storage.objects for select to authenticated using(bucket_id='user-library' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "library storage own insert" on storage.objects for insert to authenticated with check(bucket_id='user-library' and (storage.foldername(name))[1]=auth.uid()::text);
create policy "library storage own delete" on storage.objects for delete to authenticated using(bucket_id='user-library' and (storage.foldername(name))[1]=auth.uid()::text);